    X['ab'][pa,pV,hc,hC] += -1.0 * np.einsum('vw,xy,uwix,yAvI->uAiI', eta1['a'], gamma1['a'], h['aa'][a,a,c,a], t['ab'][pa,pV,ha,hC], optimize=True)
