    X['bb'][pA,pA,hA,hA] += 0.5 * np.einsum('uv,YZ,iZuU,vVWiXY->VWUX', eta1['a'], gamma1['b'], h['ab'][c,A,a,A], t['abb'][pa,pA,pA,hc,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += 0.25 * np.einsum('uv,iu,vUViWX->UVWX', eta1['a'], h['a'][c,a], t['abb'][pa,pA,pA,hc,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -0.5 * np.einsum('uv,iIuU,vVWiIX->VWUX', eta1['a'], h['ab'][c,C,a,A], t['abb'][pa,pA,pA,hc,hC,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -0.5 * np.einsum('uv,iUuA,vVAiWX->UVWX', eta1['a'], h['ab'][c,A,a,V], t['abb'][pa,pA,pV,hc,hA,hA], optimize=True)
