    X['bb'][pA,pA,hA,hA] += 0.25 * np.einsum('YZ,PQ,IUYP,VZQIWX->UVWX', eta1['b'], eta1['b'], h['bb'][C,A,A,A], t['bbb'][pA,pA,pA,hC,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -0.5 * np.einsum('YZ,uv,vUaY,aVZuWX->UVWX', eta1['b'], gamma1['a'], h['ab'][a,A,v,A], t['abb'][pv,pA,pA,ha,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -0.5 * np.einsum('YZ,PQ,IQUY,VWZIXP->VWUX', eta1['b'], gamma1['b'], h['bb'][C,A,A,A], t['bbb'][pA,pA,pA,hC,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -0.5 * np.einsum('YZ,PQ,UQYA,VZAWXP->UVWX', eta1['b'], gamma1['b'], h['bb'][A,A,A,V], t['bbb'][pA,pA,pV,hA,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -0.5 * np.einsum('YZ,iUaY,aVZiWX->UVWX', eta1['b'], h['ab'][c,A,v,A], t['abb'][pv,pA,pA,hc,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += 0.25 * np.einsum('YZ,IY,UVZIWX->UVWX', eta1['b'], h['b'][C,A], t['bbb'][pA,pA,pA,hC,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += 0.25 * np.einsum('YZ,IJUY,VWZIJX->VWUX', eta1['b'], h['bb'][C,C,A,A], t['bbb'][pA,pA,pA,hC,hC,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += 0.5 * np.einsum('YZ,IUYA,VZAIWX->UVWX', eta1['b'], h['bb'][C,A,A,V], t['bbb'][pA,pA,pV,hC,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += 0.25 * np.einsum('uv,va,aUVuWX->UVWX', gamma1['a'], h['a'][a,v], t['abb'][pv,pA,pA,ha,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -0.5 * np.einsum('uv,vIaU,aVWuIX->VWUX', gamma1['a'], h['ab'][a,C,v,A], t['abb'][pv,pA,pA,ha,hC,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -0.5 * np.einsum('uv,vUaA,aVAuWX->UVWX', gamma1['a'], h['ab'][a,A,v,V], t['abb'][pv,pA,pV,ha,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += 0.5 * np.einsum('YZ,uv,vZaU,aVWuXY->VWUX', gamma1['b'], gamma1['a'], h['ab'][a,A,v,A], t['abb'][pv,pA,pA,ha,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += 0.25 * np.einsum('YZ,PQ,ZQUA,VWAXYP->VWUX', gamma1['b'], gamma1['b'], h['bb'][A,A,A,V], t['bbb'][pA,pA,pV,hA,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += 0.5 * np.einsum('YZ,iZaU,aVWiXY->VWUX', gamma1['b'], h['ab'][c,A,v,A], t['abb'][pv,pA,pA,hc,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -0.5 * np.einsum('YZ,IZUA,VWAIXY->VWUX', gamma1['b'], h['bb'][C,A,A,V], t['bbb'][pA,pA,pV,hC,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -0.25 * np.einsum('YZ,UZAB,VABWXY->UVWX', gamma1['b'], h['bb'][A,A,V,V], t['bbb'][pA,pV,pV,hA,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += 0.25 * np.einsum('YZ,ZA,UVAWXY->UVWX', gamma1['b'], h['b'][A,V], t['bbb'][pA,pA,pV,hA,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += 0.25 * np.einsum('ia,aUViWX->UVWX', h['a'][c,v], t['abb'][pv,pA,pA,hc,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += 0.125 * np.einsum('iuvw,vwux,xUViWX->UVWX', h['aa'][c,a,a,a], lambdas['aa'], t['abb'][pa,pA,pA,hc,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -0.5 * np.einsum('iIaU,aVWiIX->VWUX', h['ab'][c,C,v,A], t['abb'][pv,pA,pA,hc,hC,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -0.5 * np.einsum('iUuV,uvwx,wxWivX->UWVX', h['ab'][c,A,a,A], lambdas['aa'], t['aab'][pa,pa,pA,hc,ha,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -1.0 * np.einsum('iUuV,uYvZ,vWZiXY->UWVX', h['ab'][c,A,a,A], lambdas['ab'], t['abb'][pa,pA,pA,hc,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -0.5 * np.einsum('iUuY,uYvZ,vVZiWX->UVWX', h['ab'][c,A,a,A], lambdas['ab'], t['abb'][pa,pA,pA,hc,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -0.5 * np.einsum('iUaA,aVAiWX->UVWX', h['ab'][c,A,v,V], t['abb'][pv,pA,pV,hc,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -0.5 * np.einsum('iYuU,uZvY,vVWiXZ->VWUX', h['ab'][c,A,a,A], lambdas['ab'], t['abb'][pa,pA,pA,hc,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -0.25 * np.einsum('iYuZ,uZvY,vUViWX->UVWX', h['ab'][c,A,a,A], lambdas['ab'], t['abb'][pa,pA,pA,hc,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += 0.125 * np.einsum('uvwa,wxuv,aUVxWX->UVWX', h['aa'][a,a,a,v], lambdas['aa'], t['abb'][pv,pA,pA,ha,hA,hA], optimize=True)
    X['bb'][pA,pA,hA,hA] += -0.5 * np.einsum('uIvU,vwux,xVWwIX->VWUX', h['ab'][a,C,a,A], lambdas['aa'], t['abb'][pa,pA,pA,ha,hC,hA], optimize=True)
