    X['0'] += -0.5 * np.einsum('UV,iIaA,WXYZ,ZAUW,aVYiIX->', gamma1['b'], h['ab'][c,C,v,V], lambdas['bb'], t['bb'][pA,pV,hA,hA], t['abb'][pv,pA,pA,hc,hC,hA], optimize=True)
    X['0'] += -0.25 * np.einsum('UV,IJAB,uvwx,wVvI,xABuJU->', gamma1['b'], h['bb'][C,C,V,V], lambdas['aa'], t['ab'][pa,pA,ha,hC], t['abb'][pa,pV,pV,ha,hC,hA], optimize=True)
    X['0'] += -0.25 * np.einsum('UV,IJAB,uvwx,xBuU,wVAvIJ->', gamma1['b'], h['bb'][C,C,V,V], lambdas['aa'], t['ab'][pa,pV,ha,hA], t['abb'][pa,pA,pV,ha,hC,hC], optimize=True)
