    X['0'] += 0.125 * np.einsum('ijab,uvwxyz,yzju,xabivw->', h['aa'][c,c,v,v], lambdas['aaa'], t['aa'][pa,pa,hc,ha], t['aaa'][pa,pv,pv,hc,ha,ha], optimize=True)
    X['0'] += 0.25 * np.einsum('ijab,uvUwxV,wxju,abVivU->', h['aa'][c,c,v,v], lambdas['aab'], t['aa'][pa,pa,hc,ha], t['aab'][pv,pv,pA,hc,ha,hA], optimize=True)
    X['0'] += -0.25 * np.einsum('ijab,uvUwxV,wauv,xbVijU->', h['aa'][c,c,v,v], lambdas['aab'], t['aa'][pa,pv,ha,ha], t['aab'][pa,pv,pA,hc,hc,hA], optimize=True)
    X['0'] += 0.25 * np.einsum('ijab,uvUwxV,wViU,xabjuv->', h['aa'][c,c,v,v], lambdas['aab'], t['ab'][pa,pA,hc,hA], t['aaa'][pa,pv,pv,hc,ha,ha], optimize=True)
    X['0'] += -0.25 * np.einsum('ijab,uvUwxV,aVvU,wxbiju->', h['aa'][c,c,v,v], lambdas['aab'], t['ab'][pv,pA,ha,hA], t['aaa'][pa,pa,pv,hc,hc,ha], optimize=True)
    X['0'] += 0.5 * np.einsum('ijab,uUVvWX,vXjU,abWiuV->', h['aa'][c,c,v,v], lambdas['abb'], t['ab'][pa,pA,hc,hA], t['aab'][pv,pv,pA,hc,ha,hA], optimize=True)
