    X['0'] += 0.5 * np.einsum('iIaA,UVWX,WI,aXAiUV->', h['ab'][c,C,v,V], lambdas['bb'], t['b'][pA,hC], t['abb'][pv,pA,pV,hc,hA,hA], optimize=True)
